    "content": "新华社华盛顿11月12日电 美国总统特朗普12日威胁称，墨西哥必须立即阻止移民车队进入美国，否则对其关税将立即翻倍。 特朗普当天在社交媒体上发帖称，随着共和党“被认为”在美国中期选举中落败，对美国的“入侵”又开始了。“庞大的‘大篷车移民队伍’正在集结，并开始穿越墨西哥的非法行进行为。……墨西哥必须立即阻止他们，如果他们不这样做，（美国）对墨西哥的关税将立即翻倍。” 特朗普还称，已将此事告知墨西哥、得克萨斯州当局、边境巡逻队以及移民和海关执法局，“绝不会手软”。"
