    "title": "军号未歇 山河铭记",
    "link": "http://www.news.cn/20261112/1caf0afe5da94c0890bc7bd36db94d17/c.html",
    "pub_date": "2026-11-12 21:31:02",
    "author": "",
    "description": "1934年10月，红六军团转战贵州石阡，陷入敌军重围，红18师52团奉命断后，掩护主力突围。面对敌军强抓百姓充当人盾，红军将士宁死不伤及群众、宁死不当俘虏，毅然砸枪跳崖。 这段历史，虽已远去，但并未消散。历史的回响，不只留在悬崖与墓碑之间，更藏在当地人的代代讲述中，沉淀为少年一代的精神印记。 今年是中国工农红军长征胜利90周年，和新华社记者一起，寻迹长征。 记者：多蕾、白志强、姜明明、张晟、卢书剑、胡心懿、崔晓强 新华社音视频部制作",
    "content": "1934年10月，红六军团转战贵州石阡，陷入敌军重围，红18师52团奉命断后，掩护主力突围。面对敌军强抓百姓充当人盾，红军将士宁死不伤及群众、宁死不当俘虏，毅然砸枪跳崖。 这段历史，虽已远去，但并未消散。历史的回响，不只留在悬崖与墓碑之间，更藏在当地人的代代讲述中，沉淀为少年一代的精神印记。 今年是中国工农红军长征胜利90周年，和新华社记者一起，寻迹长征。 记者：多蕾、白志强、姜明明、张晟、卢书剑、胡心懿、崔晓强 新华社音视频部制作"
