    "content": "香港立法会星期四（11月12日）通过《北部都会区发展条例草案》，希望加快北部都会区的土地开发和工程建设。港府的目标是争取有关措施在明年第一季生效。 北部都会区是港府重点推动的大型发展计划 ，位于新界北部，涵盖元朗、天水围、粉岭、上水及古洞等地区，规划面积约3万公顷。项目旨在增加房屋及土地供应，发展创新科技、先进制造业及现代服务业，打造香港新的经济增长引擎。 新条例提出在六大政策范畴为北部都会区发展“拆墙松绑”，分别为简化城市规划程序、加快支付收地补偿、促进工程创新及提质、简化建筑噪音许可证申请、便利跨境要素流动，以…"
