    "content": "新华社坎帕拉11月12日电（记者聂祖国）由乌干达中国和平统一促进会主办的纪念孙中山先生诞辰160周年专题座谈会日前在乌首都坎帕拉举行，旅乌侨界及中资企业代表40余人参加。 中国驻乌干达大使邬光荣致辞说，孙中山先生一生为民族独立、国家统一、人民幸福不懈奋斗。希望大家继承孙中山先生遗志，同心同行，为推进祖国统一大业、实现民族复兴作出新的更大贡献，为中乌、中非传统友谊注入新的时代内涵。 乌干达中国和平统一促进会秘书长林良土说，从百余年前海外华侨支持中国民主革命，到今天广大旅乌侨胞积极投身中乌经贸合作、文化交流和社会公益，…"
