    "content": "新华社温得和克11月12日电（记者林晶）中国援助纳米比亚医疗队派遣30周年纪念暨交流活动11日在纳首都温得和克的卡图图拉医院举行。中纳双方表示，将以医疗队派遣30周年为新起点，深化临床培训、数字健康、专科医疗服务可及性、研究创新和可持续能力建设等领域合作。 纳卫生与社会服务部副部长恩贾莱卡在致辞中说，过去30年的医疗合作为两国进一步加强卫生机构间交流奠定坚实基础。纳方期待双方在专科交流、护理培训、临床带教和医院管理等方面深化合作，并拓展数字医疗、远程医疗和联合临床研究，让纳米比亚医疗资源相对不足的偏远地区居民获得更…"
