    "title": "蒙古族拉弦乐器制作技艺：让草原弦音绵延不绝",
    "link": "http://www.news.cn/20261112/0df1239448fc45f1b608a574e42c2ac5/c.html",
    "pub_date": "2026-11-12 20:55:42",
    "author": "",
    "description": "蒙古族拉弦乐器有潮尔、马头琴、四胡，制作技艺与陶力、好来宝、乌力格尔等相互依存。 内蒙古科尔沁右翼中旗是代表性传承地，制琴经选材、塑形、蒙皮、上弦、调音等工序，匠人须懂音律、善木工、会设计。 2011年，该技艺被列入第三批国家级非物质文化遗产代表性项目名录。 作者：张晟、张硕 新华社音视频部制作",
    "content": "蒙古族拉弦乐器有潮尔、马头琴、四胡，制作技艺与陶力、好来宝、乌力格尔等相互依存。 内蒙古科尔沁右翼中旗是代表性传承地，制琴经选材、塑形、蒙皮、上弦、调音等工序，匠人须懂音律、善木工、会设计。 2011年，该技艺被列入第三批国家级非物质文化遗产代表性项目名录。 作者：张晟、张硕 新华社音视频部制作"
