    "description": "新华社台北11月12日电（记者周文其、李寒芳）11月12日是孙中山先生诞辰160周年纪念日，台湾各界举办多场纪念活动，表达对孙中山先生的敬仰和缅怀之情。 当日上午，艳阳高照，位于台北市仁爱路的孙中山纪念馆人流比以往多了不少，各界人士前来缅怀孙中山先生。 中国国民党、新党、台北市广东同乡会等团体上百人来到纪念馆园区的中山碑林，依序向孙中山铜像致敬行礼。 参加活动的台北市民李先生告诉记者，多年来每到这天，都会来此缅怀孙中山先生。“中山先生为…",
    "content": "新华社台北11月12日电（记者周文其、李寒芳）11月12日是孙中山先生诞辰160周年纪念日，台湾各界举办多场纪念活动，表达对孙中山先生的敬仰和缅怀之情。 当日上午，艳阳高照，位于台北市仁爱路的孙中山纪念馆人流比以往多了不少，各界人士前来缅怀孙中山先生。 中国国民党、新党、台北市广东同乡会等团体上百人来到纪念馆园区的中山碑林，依序向孙中山铜像致敬行礼。 参加活动的台北市民李先生告诉记者，多年来每到这天，都会来此缅怀孙中山先生。“中山先生为国家统一和民族复兴奉献一生。两岸民众都应当纪念他，并追随他的精神继续前进。” “…"
