    "content": "据外交部网站消息，11月11日，中共中央政治局委员、外交部长王毅同美国国务卿鲁比奥通电话。双方就中美关系及两国元首互动深入交换意见，通话是积极和建设性的。 王毅表示，中美关系稳定势头来之不易，是两个大国从各自和共同利益出发作出的理性选择。中国对美政策保持稳定性和连续性，愿同美方加强沟通合作，妥善处理分歧和敏感问题，相互支持办好2026年亚太经合组织领导人非正式会议和二十国集团领导人峰会，推动中美建设性战略稳定关系落地见效。 这场通话是近期中美高层沟通的一个缩影。2026年亚太经合组织（APEC）第三十三次领导人非正…"
