    "content": "新华社香港11月12日电（记者肖逸晨）香港特别行政区政府12日上午在中山纪念公园举行孙中山先生诞辰160周年纪念仪式，缅怀孙中山先生为民族独立、社会进步、人民幸福建立的不朽功勋。 香港特区行政长官李家超主持纪念仪式并致辞表示，孙中山先生一生以革命为己任，立志救国救民。孙中山先生的爱国思想、革命意志和进取精神，是我们每一位中华儿女都应该学习和传承的。 李家超说，孙中山先生和香港有着深厚的渊源，香港既是他革命思想的缘起之地，也是日后策划起义的重要基地。纪念孙中山先生最好的方式，就是学习和继承他振兴中华的伟大志向、热爱祖…"
