    "description": "中新网银川11月12日电 (记者 于晶)11月12日，记者从宁夏回族自治区自然资源厅获悉，《宁夏自然资源保护利用“十五五”规划》紧密衔接自治区“十五五”发展规划、国土空间规划，推动资源管理从“重开发保障”向“重保护提质、精准保障、系统治理”深度转型。",
    "content": "中新网银川11月12日电 (记者 于晶)11月12日，记者从宁夏回族自治区自然资源厅获悉，《宁夏自然资源保护利用“十五五”规划》紧密衔接自治区“十五五”发展规划、国土空间规划，推动资源管理从“重开发保障”向“重保护提质、精准保障、系统治理”深度转型。"
