    "content": "新华社北京11月12日电（记者王聿昊、谢希瑶）商务部新闻发言人何亚东在商务部12日举行的例行新闻发布会上说，“300亿对300亿”对等降税框架安排有利于稳定和拓展中美双边贸易，中美两国工商界对此都抱有较高期待。目前，中美双方就实施这一安排保持密切沟通。 “希望美方与中方共同努力，尽快推动这一安排落地见效，为两国农产品贸易创造更多有利条件。”何亚东说。 在回应有关经贸磋商的提问时，何亚东介绍，中美双方正在就贸易、投资等领域各自关切问题保持密切沟通，有关进展将适时公布。 谈及当前中美经贸关系，何亚东表示，2025年5月…"
