    "description": "Meta宣布与多家供应商签署长期采购协议，涉及低碳水泥、近零排放钢铁、电动卡车运输及再生塑料，以推动数据中心供应链相关产业采用低碳制造技术。其中，Meta与Sublime Systems签署多年期协议，支持至少18万吨低碳水泥生产；与瑞典钢铁企业Stegra签署多年期协议，支持近零排放原生钢铁生产；与MacroCycle Technologies达成长期采购协议，支持其在美国东南部建设商业化工厂，目标每年生产5000吨高价值再生PET。…",
