    "title": "俄副外长谈三方会谈：建立功能性机制需有政治意愿",
    "link": "http://www.news.cn/20261112/e828b2fee85d4fdbaef2e54da1e24884/c.html",
    "pub_date": "2026-11-12 20:16:13",
    "author": "",
    "description": "新华社莫斯科11月12日电（记者黄河）据俄罗斯媒体12日报道，俄外交部副部长里亚布科夫表示，俄罗斯、美国、乌克兰在阿联酋首都阿布扎比举行的三方会谈成果表明，只要有政治意愿，就有可能建立起某种功能性机制。 里亚布科夫在接受今日俄罗斯电视台采访时说，这次三方会谈重点关注在欧洲地区和当前冲突地区建立安全架构的前景，“这一前景有可能确保未来达成协议的可持续性，并将目前的紧张和升级趋势转变为共存”。 里亚布科夫表示，目前谈论恢复各方信任还为时过早…",
    "content": "新华社莫斯科11月12日电（记者黄河）据俄罗斯媒体12日报道，俄外交部副部长里亚布科夫表示，俄罗斯、美国、乌克兰在阿联酋首都阿布扎比举行的三方会谈成果表明，只要有政治意愿，就有可能建立起某种功能性机制。 里亚布科夫在接受今日俄罗斯电视台采访时说，这次三方会谈重点关注在欧洲地区和当前冲突地区建立安全架构的前景，“这一前景有可能确保未来达成协议的可持续性，并将目前的紧张和升级趋势转变为共存”。 里亚布科夫表示，目前谈论恢复各方信任还为时过早，但需要建立某种功能性机制，避免局势失控升级。“鉴于过去两天的讨论，只要有足够的…"
