    "content": "中共总书记习近平星期四（11月12日）提出愿在坚持一中原则和“九二共识”的基础上，同台湾各界有识之士就两岸关系和国家统一开展对话协商。台湾蓝营人士同一天也发起两岸和平倡议，提出由民间先行协商，为两岸官方恢复沟通创造条件。 中国大陆星期四举行孙中山诞辰160周年纪念大会 ，习近平发表讲话时强调，解决台湾问题、实现两岸统一是“实现中华民族伟大复兴的必然要求”；并提出在“坚持一个中国原则和‘九二共识’的基础上，愿意同台湾各界有识之士就两岸关系和国家统一开展对话协商”。 具有泛蓝色彩的台湾民间智库民主文教基金会当天上午也在…"
