    "content": "11月12日，国务院以“健全多层次社会保障体系，进一步织密扎牢社会保障安全网”为主题，进行第二十二次专题学习。国务院总理李强在主持学习时强调，进一步深化社会保障制度改革，健全覆盖全民、统筹城乡、公平统一、安全规范、可持续的多层次社会保障体系，推动现代化建设成果更多更公平惠及全体人民。加快补齐社会保障体系短板，扩大企业年金覆盖面，提高个人养老金制度吸引力，支持商业健康保险发展壮大，稳妥有序推进长期护理保险制度建设。增强社保基金长期可持续性，完善并落实职工养老保险全国统筹制度，推进基本医疗保险省级统筹，强化社保基金安全…"
