    "content": "新华社北京11月12日电（记者刘慧、潘清）记者11月12日从中国证监会获悉，证监会相关负责同志在2026年上海证券交易所国际投资者大会上表示，证监会将丰富市场投资工具，加大权益类产品供给和创新力度，引导和鼓励主动ETF加快投资建仓。进一步拓宽中长期资金来源、渠道和入市方式，促进融资融券逆周期调节功能发挥，汇聚各方合力，全力维护市场平稳运行。 证监会相关负责同志表示，证监会将完善稳市机制，增强股市内在稳定性，会同相关部门协同发力，打好稳市场、稳预期政策组合拳。用好用足两项结构性货币政策工具，证券、基金公司已开展第三批…"
