    "content": "新华社都柏林11月12日电（记者张兆卿 赵家淞）第九届欧洲政治共同体领导人会议12日在爱尔兰首都都柏林举行，聚焦欧洲安全与竞争力等议题。 本届会议以“欧洲——强大、安全、互联”为主题。与会者围绕提升欧洲竞争力、维护欧洲民主与安全两大议题展开对话，其中竞争力议题涉及创新、互联互通和可负担的能源等。约50位欧洲国家元首或政府首脑、欧洲和国际机构负责人出席。 乌克兰总统泽连斯基11日抵达都柏林，计划与约20位领导人举行双边或多边会晤。他预计12日晚同美国总统特使威特科夫和美国总统特朗普的女婿库什纳会晤。 欧洲政治共同体由…"
