    "title": "于魁智、李胜素等大陆戏曲名家将来台献艺",
    "link": "http://www.news.cn/20261112/de04bde07147458da4238f7790b7c519/c.html",
    "pub_date": "2026-11-12 19:43:47",
    "author": "",
    "description": "新华社台北11月12日电（记者周文其、李寒芳）大陆知名京剧表演艺术家于魁智、李胜素领衔的大陆戏曲名家一行80人，将于11月17日至22日在台北举行多场精彩演出，给台湾戏迷带来引人入胜的经典好戏。 演出邀请方台湾传大艺术事业有限公司12日在台北举行记者会。据介绍，此次节目包括《四郎探母》《杨门女将》《太真外传》《红鬃烈马》等，好戏连台，让戏迷们过足瘾。 于魁智说，非常高兴再次来到台湾和广大观众见面。每次来台演出，都有许多台湾戏迷为我们加油…",
    "content": "新华社台北11月12日电（记者周文其、李寒芳）大陆知名京剧表演艺术家于魁智、李胜素领衔的大陆戏曲名家一行80人，将于11月17日至22日在台北举行多场精彩演出，给台湾戏迷带来引人入胜的经典好戏。 演出邀请方台湾传大艺术事业有限公司12日在台北举行记者会。据介绍，此次节目包括《四郎探母》《杨门女将》《太真外传》《红鬃烈马》等，好戏连台，让戏迷们过足瘾。 于魁智说，非常高兴再次来到台湾和广大观众见面。每次来台演出，都有许多台湾戏迷为我们加油鼓劲，这让我们非常感动。为了这次来台演出，我们做了精心筹划和准备，力争会聚更多名…"
