    "description": "新华社北京11月12日电 中央宣讲团成员、中共中央政治局委员、中央组织部部长石泰峰12日在中央组织部机关宣讲党的二十届五中全会精神。 石泰峰紧紧围绕学习贯彻习近平总书记在全会上的重要讲话精神和全会《决定》，从深刻领会把握全会的重大意义，深刻领会把握新时代全面从严治党的伟大成就，深刻领会把握持之以恒推进全面从严治党重要性紧迫性和总体要求、战略任务、重大举措等方面，作了系统阐释和深入解读。 石泰峰表示，党的十八大以来，正是以习近平同志为核心…",
    "content": "新华社北京11月12日电 中央宣讲团成员、中共中央政治局委员、中央组织部部长石泰峰12日在中央组织部机关宣讲党的二十届五中全会精神。 石泰峰紧紧围绕学习贯彻习近平总书记在全会上的重要讲话精神和全会《决定》，从深刻领会把握全会的重大意义，深刻领会把握新时代全面从严治党的伟大成就，深刻领会把握持之以恒推进全面从严治党重要性紧迫性和总体要求、战略任务、重大举措等方面，作了系统阐释和深入解读。 石泰峰表示，党的十八大以来，正是以习近平同志为核心的党中央深谋远虑、直面问题、力挽狂澜，坚定不移推进全面从严治党，才有今天这样空前…"
