    "description": "新华社伦敦11月12日电 题：走近中国，更新眼光 新华社记者高文成 英国美食作家扶霞·邓洛普日前在英国《金融时报》发表文章，谈及自己对豆汁儿——北京胡同里的这口滋味如何念念不忘，甚至在伦敦尝试复刻。她由此谈到，在伦敦，从四川豆瓣酱到湖南臭豆腐，中国的各地风味不难寻觅。但身边的选择再丰富，也挡不住她实地踏访中国的脚步：有些滋味，终究要到当地去尝。 一道菜可成为认识中国的一扇窗，但隔窗只能看见一角风景，置身中国，方知天地宽广。中国国家移民管…",
    "content": "新华社伦敦11月12日电 题：走近中国，更新眼光 新华社记者高文成 英国美食作家扶霞·邓洛普日前在英国《金融时报》发表文章，谈及自己对豆汁儿——北京胡同里的这口滋味如何念念不忘，甚至在伦敦尝试复刻。她由此谈到，在伦敦，从四川豆瓣酱到湖南臭豆腐，中国的各地风味不难寻觅。但身边的选择再丰富，也挡不住她实地踏访中国的脚步：有些滋味，终究要到当地去尝。 一道菜可成为认识中国的一扇窗，但隔窗只能看见一角风景，置身中国，方知天地宽广。中国国家移民管理局数据显示，今年三季度，外国人入境达1160.1万人次，同比上升15.6%；其…"
