    "title": "蓝盾光电：拟13.5亿元收购苏州岚创100％股权并配套募资",
    "link": "https://36kr.com/newsflashes/4066686838772868?f=rss",
    "pub_date": "2026-11-12 19:38:40",
    "author": "",
    "description": "36氪获悉，蓝盾光电公告，公司拟通过发行股份及支付现金方式购买郑燕飞等7名交易对方合计持有的苏州岚创科技有限公司100%股权，并向不超过35名特定投资者发行股份募集配套资金不超过7亿元。本次交易作价13.5亿元，其中现金对价6.08亿元、股份对价7.42亿元。标的公司主营高性能真空镀膜设备研发制造，2026年1-8月实现营业收入2.62亿元、净利润1.47亿元。本次交易构成关联交易及重大资产重组，不构成重组上市。",
    "content": "36氪获悉，蓝盾光电公告，公司拟通过发行股份及支付现金方式购买郑燕飞等7名交易对方合计持有的苏州岚创科技有限公司100%股权，并向不超过35名特定投资者发行股份募集配套资金不超过7亿元。本次交易作价13.5亿元，其中现金对价6.08亿元、股份对价7.42亿元。标的公司主营高性能真空镀膜设备研发制造，2026年1-8月实现营业收入2.62亿元、净利润1.47亿元。本次交易构成关联交易及重大资产重组，不构成重组上市。"
