    "content": "达喀尔青奥会的圣火即将熄灭 一批未来之星已冉冉升起 他们闪耀青奥会赛场 也向世界宣告 他们志在成为世界体坛的 未来主角 10月31日，演员在开幕式上组成奥运五环。新华社记者 那宇奇 摄 常墨涵： 一日双金的“水蝴蝶” 15岁的游泳小将常墨涵 是中国代表团开幕式旗手之一 虽然前两个项目出师不利 无缘女子200米蛙泳和混合泳金牌 让她一度沮丧、流泪 但最后一天她“一日游三枪” 顶着高温和感冒 在200米自由泳和200米蝶泳中 双双夺金 以2金2银 成为本届赛事奖牌最多的中国选手之一 不过她谦虚地表示 自己的经验、技术、…"
