    "content": "新华社昆明11月12日电（记者严勇）学习贯彻党的二十届五中全会精神中央宣讲团报告会11月12日在云南省昆明市举行，中央宣讲团成员、中央纪委副书记、国家监委副主任张福海作宣讲报告。 报告会上，张福海紧扣宣讲主题，围绕学习贯彻习近平总书记在全会上的重要讲话精神和全会通过的《决定》，从深刻把握持之以恒推进全面从严治党的重大意义，深刻把握新时代全面从严治党的伟大成就，深刻把握持之以恒推进全面从严治党的总体要求、战略任务和重大举措，深刻把握中国特色反腐败之路的科学内涵和实践要求等方面，对全会精神作了系统宣讲和深入阐释。 张福…"
