    "content": "新华社加沙/耶路撒冷11月12日电（记者徐泽宇 庞昕熠）据巴勒斯坦通讯社12日报道，以色列军队当天对加沙地带南部城市汗尤尼斯的一家医院发动空袭，造成至少6人死亡、超过20人受伤。以方同日发表声明称，对该医院内的巴勒斯坦伊斯兰抵抗运动（哈马斯）高级别武装人员发动“精准打击”，目标包括哈马斯汗尤尼斯旅指挥官穆罕默德·阿布·伊斯梅尔等人。 加沙当地卫生部门表示，遭袭的是汗尤尼斯市纳赛尔医院，6名死者中包括医生、患者和陪护人员。 以色列国防军与以色列国家安全总局（辛贝特）在联合声明中称，伊斯梅尔和其他一些藏身于纳赛尔医院内…"
