    "title": "泽连斯基抱怨乌军使用“星盾”再遭限速",
    "link": "http://www.news.cn/20261112/8325c99475e84549b1315abbde555595/c.html",
    "pub_date": "2026-11-12 18:55:40",
    "author": "",
    "description": "新华社基辅11月12日电 乌克兰总统泽连斯基12日说，连日来，乌军使用的“星盾”卫星通信系统运行出现“重大中断”，导致乌军拦截俄罗斯无人机的难度大幅增加，已有一些俄方袭击突破乌方防御。 泽连斯基在社交媒体上说，他听取了乌克兰国防部长叶夫根尼·赫马拉和乌克兰武装部队总司令米哈伊洛·德拉帕特的简报。“不幸的是，我们的部队连日来记录到‘星盾’在乌克兰领土上的运行出现重大中断——整个前线及乌克兰暂时被占领土均是如此。” 泽连斯基写道：“具体而言…",
    "content": "新华社基辅11月12日电 乌克兰总统泽连斯基12日说，连日来，乌军使用的“星盾”卫星通信系统运行出现“重大中断”，导致乌军拦截俄罗斯无人机的难度大幅增加，已有一些俄方袭击突破乌方防御。 泽连斯基在社交媒体上说，他听取了乌克兰国防部长叶夫根尼·赫马拉和乌克兰武装部队总司令米哈伊洛·德拉帕特的简报。“不幸的是，我们的部队连日来记录到‘星盾’在乌克兰领土上的运行出现重大中断——整个前线及乌克兰暂时被占领土均是如此。” 泽连斯基写道：“具体而言，（乌方使用）‘星盾’正被系统性地施加速度限制，即被限制在每小时161公里以下。…"
