    "content": "地产退潮后，ESG成为陶瓷行业竞争力重塑的关键部分。 南方周末研究员 康华 责任编辑：孙孝文 佛山，窑炉跳动的火焰，曾是这座千年陶都最炽热的产业脉搏。 高温烧制之后，一块块瓷砖从生产线上出来，被送往全国各地的工地、建材市场和家装门店。很长一段时间，陶瓷生意与房地产高度绑定，楼市扩张，瓷砖需求随之增长。 房地产下行后，需求收缩、订单减少，佛山陶瓷进入“缩量竞争、优胜劣汰”的调整期。曾经的增长确定性消失，如果活下去都成问题，ESG如何为陶瓷企业创造价值？带着这个问题，我们与中国陶瓷工业协会常务理事、佛山市禅城区陶瓷行业…"
