    "description": "中国邮政星期四（11月12日）发行孙中山诞辰160周年纪念邮票。 据新华社报道，中国邮政星期四发行《纪念孙中山先生诞辰160周年》纪念邮票小型张，计划发行数量320万套。 纪念邮票小型张以油画方式创作，边饰为孙中山题词“天下为公”。 纪念邮票小型张将在中国指定邮政网点、集邮网厅、中国邮政手机客户端等渠道出售，出售期限六个月。 中国官方去年宣布将举办纪念孙中山诞辰160周年活动。一个多月来，南京、上海、厦门、广州等地先后举行以纪念孙中山为…",
    "content": "中国邮政星期四（11月12日）发行孙中山诞辰160周年纪念邮票。 据新华社报道，中国邮政星期四发行《纪念孙中山先生诞辰160周年》纪念邮票小型张，计划发行数量320万套。 纪念邮票小型张以油画方式创作，边饰为孙中山题词“天下为公”。 纪念邮票小型张将在中国指定邮政网点、集邮网厅、中国邮政手机客户端等渠道出售，出售期限六个月。 中国官方去年宣布将举办纪念孙中山诞辰160周年活动。一个多月来，南京、上海、厦门、广州等地先后举行以纪念孙中山为主题的音乐会和展览等活动。 纪念孙中山诞辰160周年大会星期四上午在北京举行，中…"
