    "description": "新华社北京11月12日电（记者彭韵佳、顾天成）11月12日是世界肺炎日。肺炎绝非“扛一扛就能过去的重感冒”，肺炎防控对免疫力尚不健全的儿童来说十分重要，家长要提高对防治及相关疫苗的认知，降低儿童患病和重症风险。 儿童肺炎链球菌疾病防控与疫苗应用研讨会近日在京举行，这是记者从会上获悉的。 专家介绍，肺炎是肺实质感染引起的炎症性疾病，常见病原体包括细菌、病毒以及支原体、衣原体等。病原体侵入肺泡后引发炎症和渗出，患者常出现发热、咳嗽、咳痰、胸…",
    "content": "新华社北京11月12日电（记者彭韵佳、顾天成）11月12日是世界肺炎日。肺炎绝非“扛一扛就能过去的重感冒”，肺炎防控对免疫力尚不健全的儿童来说十分重要，家长要提高对防治及相关疫苗的认知，降低儿童患病和重症风险。 儿童肺炎链球菌疾病防控与疫苗应用研讨会近日在京举行，这是记者从会上获悉的。 专家介绍，肺炎是肺实质感染引起的炎症性疾病，常见病原体包括细菌、病毒以及支原体、衣原体等。病原体侵入肺泡后引发炎症和渗出，患者常出现发热、咳嗽、咳痰、胸痛、呼吸急促和乏力等表现。 “肺炎绝非‘扛一扛就能过去的重感冒’。”南京医科大学…"
