    "description": "新华社北京11月12日电 题：规范技能人才评价活动 首部行政法规征求意见 新华社记者张晓洁 技能人才评价一头连着职业教育和技能培训，一头连着就业增收，是体现劳动者技能价值的重要载体。为规范技能人才评价活动，人力资源社会保障部11月12日发布《技能人才评价条例（征求意见稿）》，从即日起至12月12日，向社会公开征求意见。 近年来，我国加快建立科学化、社会化、市场化的人才评价制度。其中，水平评价类技能人员职业资格逐步由政府认定改为社会化等级…",
    "content": "新华社北京11月12日电 题：规范技能人才评价活动 首部行政法规征求意见 新华社记者张晓洁 技能人才评价一头连着职业教育和技能培训，一头连着就业增收，是体现劳动者技能价值的重要载体。为规范技能人才评价活动，人力资源社会保障部11月12日发布《技能人才评价条例（征求意见稿）》，从即日起至12月12日，向社会公开征求意见。 近年来，我国加快建立科学化、社会化、市场化的人才评价制度。其中，水平评价类技能人员职业资格逐步由政府认定改为社会化等级认定。截至2025年末，我国技能人才评价机构数量达3.2万家，2025年全年取得…"
