    "content": "新华社墨尔本11月12日电（记者徐海静 熊文苑）莫尔兹比港消息：据巴布亚新几内亚《信使邮报》12日报道，巴新总理马拉佩近日说，巴新关闭“驻巴新台北经济办事处”是经过慎重考虑作出的独立外交决定，符合巴新长期奉行的一个中国原则和巴新国家利益。 巴新政府7月15日宣布关闭“驻巴新台北经济办事处”。《信使邮报》报道说，马拉佩对此表示，“巴新是独立主权国家，外交政策由自身国家利益决定”。 马拉佩还说，自1976年与中华人民共和国建立外交关系以来，巴新始终坚定恪守一个中国原则。“这不是本届政府推出的新政策，而是一个延续了50年…"
