    "description": "“以中国式现代化全面推进强国建设、民族复兴伟业，是中国共产党和中国人民的新长征，也是实现孙中山先生‘振兴中华’理想的必由之路。”在纪念孙中山先生诞辰160周年大会上，习近平总书记发表重要讲话，深切缅怀孙中山先生的不朽功勋，就学习继承发扬孙中山先生宝贵精神、激励全体中华儿女团结奋斗提出明确要求，激荡起心往一处想、劲往一处使、实现中华民族伟大复兴的强烈共鸣。 中国共产党人是孙中山先生革命事业最坚定的支持者、最忠诚的合作者、最忠实的继承者。1…",
