    "content": "新华社北京11月12日电（记者岳东兴、公兵）12日在马来西亚吉隆坡亚足联总部举行的抽签仪式上，2028年洛杉矶奥运会女足项目亚洲区预选赛分组揭晓，中国队与朝鲜、韩国、菲律宾队同组。 此次抽签前，亚足联将八支球队分成四档，每档两队，分档依据是国际足联今年10月20日发布的世界排名。由于中国女足排在日本、朝鲜、澳大利亚、韩国队之后，因此被分到第三档，意味着同组对手中至少有两支强队，晋级之路也将更为艰难。 A组的四支球队为：日本、澳大利亚、中国台北、乌兹别克斯坦队；B组的四支球队为朝鲜、韩国、中国、菲律宾队。这八支球队将…"
