    "description": "台湾正研拟设立主权基金的法案，计划设立一支初始资本约为300亿元新台币（约11.7亿新元）的主权财富基金，推进政府在海外进行战略投资的计划。 综合彭博社、台湾《经济日报》等报道，台湾国发会主委叶俊显星期三（11月11日）透露，规划已进入法条研拟阶段，预计年底前提出专法草案。 叶俊显说，主权基金的资金来源可能包括台湾央行外汇储备、政府发行特别公债或引入民间资本。他补充说，基金的潜在投资领域包括原材料和科技企业。 台湾总统赖清德去年宣布将设…",
    "content": "台湾正研拟设立主权基金的法案，计划设立一支初始资本约为300亿元新台币（约11.7亿新元）的主权财富基金，推进政府在海外进行战略投资的计划。 综合彭博社、台湾《经济日报》等报道，台湾国发会主委叶俊显星期三（11月11日）透露，规划已进入法条研拟阶段，预计年底前提出专法草案。 叶俊显说，主权基金的资金来源可能包括台湾央行外汇储备、政府发行特别公债或引入民间资本。他补充说，基金的潜在投资领域包括原材料和科技企业。 台湾总统赖清德去年宣布将设立主权基金，以协助台湾企业拓展全球市场，加强台北与各地市场的联系，并反制中国大陆…"
