    "content": "新华社北京11月12日电 题：确认糖尿病，是否彻底跟甜食绝缘 新华社记者黄筱、龚雯 确诊糖尿病，就意味着彻底跟甜食绝缘了？11月14日是联合国糖尿病日，专家支招，教患者在满足口腹之欲的同时稳住血糖。 “糖尿病患者并非完全不能吃甜食，核心在于控制食物的升糖指数（GI）和整体饮食的平衡。”浙江省医学会糖尿病分会主任委员、浙江大学医学院附属第二医院内分泌科主任郑超表示，人体依然需要适量的碳水化合物来维持基础代谢，完全禁糖不仅难以坚持，还可能引发心理上的补偿性暴食。 如果患者偶尔想吃点甜，专家建议可以通过以下几个技巧来解馋…"
