    "pub_date": "2026-11-12 17:00:00",
    "author": "",
    "description": "中国商业电气机械和器材制造业过去几十年反复上演的剧本是：一个赛道从无到有，靠的是政策和资本；从有到强，靠的是规模化和技术实力；从强到久，靠的是模式和耐心。光伏如此，动力电池如此，储能也不会例外。 南方周末研究员 柯玉圆 责任编辑：黄金萍 光伏主业深陷亏损、动力电池毛利变薄，储能会是光伏企业的“救星”、电池厂商的新引擎吗？ 南方周末2026年度中国企业科创力数据库收录了商业电气机械和器材制造业企业共363家。电池厂商成了行业科创力TOP1…",
    "content": "中国商业电气机械和器材制造业过去几十年反复上演的剧本是：一个赛道从无到有，靠的是政策和资本；从有到强，靠的是规模化和技术实力；从强到久，靠的是模式和耐心。光伏如此，动力电池如此，储能也不会例外。 对此刻仍在牌桌上的玩家而言，出货量和市占率只是阶段性的成绩单，技术路线、系统集成与商业模式，才是角逐的关键。行业洗牌仍在继续，风口的红利或许属于最先上桌者，但周期的红利往往留给最能熬者。 南方周末研究员 柯玉圆 责任编辑：黄金萍 光伏主业深陷亏损 、 动力电池毛利变薄，储能 会是 光伏企业的 “ 救星 ” 、电池厂商的新引…"
