    "content": "新华社北京11月12日电 美国新一届国会的任期将于2027年1月初开始。民主党人在中期选举中夺回参众两院后，已提出以两项移民法案作为改革起点。 这是11月3日在美国首都华盛顿拍摄的国会大厦。新华社记者李睿摄 一些民主党籍议员11日在国会大厦外举行记者会，宣布将推进两党部分议员先前共同提出的《梦想与承诺法案》和《尊严法案》。前者将为移民儿童提供获得公民身份的途径，后者将拓宽移民劳工获得居留身份的渠道。 据国会工作人员透露，民主党内已拟定针对国土安全部的调查事项清单，包括移民拘留中心情况、移民执法行动致死事件、拨款使用…"
